custom.expression:
let drift_t = t * drift;
let sun_p = vec2<f32>(0.25, 0.2);
let sun_d = length(p - sun_p);
let sun = fill(sun_d - 0.085);
let glow = halo(sun_d - 0.085, 0.4);
let n1 = noise(vec2<f32>(p.x * 2.5 + drift_t * 0.04, 1.0));
let n2 = noise(vec2<f32>(p.x * 3.5 - drift_t * 0.06, 5.0));
let n3 = noise(vec2<f32>(p.x * 2.0 + drift_t * 0.03, 9.0));
let h1 = -0.14 + 0.07 * sin(p.x * 3.0 + drift_t * 0.12) + 0.05 * (n1 - 0.5);
let h2 = -0.03 + 0.06 * sin(p.x * 4.5 - drift_t * 0.09 + 1.3) + 0.05 * (n2 - 0.5);
let h3 = 0.07 + 0.05 * sin(p.x * 6.0 + drift_t * 0.07 + 2.6) + 0.04 * (n3 - 0.5);
let haze_col = mix(c5, c1, 0.4);
let sky = mix(c4 * 0.6, c2 * 0.55, smoothstep(-0.5, 0.5, p.y)) + haze_col * (glow * 0.45 + sun * 0.7);
var scene = sky + c5 * sun;
scene = mix(scene, mix(c3 * 0.85, haze_col, 0.35), fill(p.y - h3));
scene = mix(scene, c2 * 0.95, fill(p.y - h2));
scene = mix(scene, c4 * 0.8, fill(p.y - h1));
let crest = stroke(p.y - h2, 0.008) * c1 * 0.8 + stroke(p.y - h1, 0.006) * c1 * 0.5;

var birds = 0.0;
for (var i = 0; i < 3; i++) {
    let k = f32(i);
    let seed = hash(vec2<f32>(k * 3.1, 7.0));
    let fr = fract(t * (0.03 + 0.02 * seed) + seed);
    let on = 1.0 - step(0.2, fr);
    let lx = fr * 5.0;
    let bpos = vec2<f32>(-1.2 + 2.4 * lx, 0.3 + 0.08 * k + 0.02 * sin(t * 1.5 + k));
    let q = p - bpos;
    let flap = 0.03 * sin(t * 9.0 + k * 2.0);
    let wing = min(sd_segment(q, vec2<f32>(0.0, 0.0), vec2<f32>(0.035, 0.012 + flap)), sd_segment(q, vec2<f32>(0.0, 0.0), vec2<f32>(-0.035, 0.012 + flap)));
    birds += (1.0 - smoothstep(0.0015, 0.0045, wing)) * on;
}

let fr2 = fract(t * 0.035 + 0.5);
let fon = 1.0 - step(0.12, fr2);
let fl = fr2 / 0.12;
let fpos = vec2<f32>(mix(0.1, 0.5, fl), -0.04 + 1.28 * fl * (1.0 - fl));
let ang = atan2(1.28 * (1.0 - 2.0 * fl), 0.4);
let fq = rotate(p - fpos, -ang);
let body = sd_segment(fq, vec2<f32>(-0.022, 0.0), vec2<f32>(0.018, 0.0)) - 0.008;
let tail = sd_segment(fq, vec2<f32>(0.016, 0.0), vec2<f32>(0.034, 0.011)) - 0.003;
let fish = (1.0 - smoothstep(0.0, 0.003, min(body, tail))) * fon;

let color = tonemap(scene + crest + c5 * birds * 0.9 + mix(c2, c5, 0.5) * fish * 1.3);
return mix(bg, color, strength);
